UPDATE definition_problem
SET query = 'SELECT name, CONCAT(''{"placeId":'', id, '',"countryGeoJson":{"type":"FeatureCollection","features":['', (SELECT GROUP_CONCAT(REPLACE(json, ''"geometry":'', CONCAT(''"properties":{"name":"'', ci.name, ''"},"geometry":'')) SEPARATOR '','') FROM region_geographical rg INNER JOIN category_identifier ci ON rg.category_id = ci.id WHERE rg.country = data.country), '']}}'') FROM (SELECT pi.name, pi.country, pi.id FROM category_summary cs INNER JOIN place_identifier pi ON cs.place_id = pi.id INNER JOIN place_event pe ON pi.id = pe.place_id WHERE pe.start < UNIX_TIMESTAMP() AND NOT EXISTS(SELECT * FROM country_specific_category_identifier csci WHERE FIND_IN_SET(csci.id, cs.category_ids))) data WHERE country IN (SELECT * FROM country_with_more_than_one_place)'
WHERE name = 'PLACES_WITHOUT_ADMINISTRATIVE_CATEGORY'